# Original assisted procedures. Data only: no process launch, network, CIM or writes.
function Get-GoatAdvancedValue {
    param($Object,[string]$Path)
    $value=$Object
    foreach($part in $Path.Split('.')){
        if($null -eq $value){return $null}
        if($value -is [Collections.IDictionary]){if(-not $value.Contains($part)){return $null};$value=$value[$part]}
        else{$property=$value.PSObject.Properties[$part];if(-not $property){return $null};$value=$property.Value}
    }
    return $value
}
function Get-GoatAdvancedSettingsAllowlist {
    @('ms-settings:windowsdefender','ms-settings:windowsupdate','ms-settings:privacy','ms-settings:privacy-feedback','ms-settings:powersleep','ms-settings:network-status','ms-settings:display-advancedgraphics','ms-settings:about','ms-settings:windowsinsider')
}
function Test-GoatAdvancedSettingsUri {
    param([string]$Uri)
    return ($Uri -in @(Get-GoatAdvancedSettingsAllowlist))
}
function Test-GoatAdvancedSourceUrl {
    param([string]$Url)
    $uri=$null
    if(-not [uri]::TryCreate($Url,[UriKind]::Absolute,[ref]$uri) -or $uri.Scheme -ne 'https' -or $uri.UserInfo -or $uri.Port -ne 443){return $false}
    foreach($hostName in @('microsoft.com','amd.com','intel.com','nvidia.com')){if($uri.DnsSafeHost -eq $hostName -or $uri.DnsSafeHost.EndsWith('.'+$hostName)){return $true}}
    return $false
}
function Get-GoatAdvancedGuideDefinitions {
    $settings='https://learn.microsoft.com/en-us/windows/apps/develop/launch/launch-settings'
    $power='https://learn.microsoft.com/en-us/windows-hardware/design/device-experiences/powercfg-command-line-options'
    $security='https://support.microsoft.com/en-us/windows/security/windows-security/device-security-in-the-windows-security-app'
    $bcd='https://learn.microsoft.com/en-us/windows-hardware/drivers/devtest/bcdedit--set'
    $ram='https://learn.microsoft.com/en-us/sysinternals/downloads/rammap'
    $amd='https://www.amd.com/en/resources/support-articles/faqs/DH3-020.html'
    $nv='https://www.nvidia.com/content/Control-Panel-Help/vLatest/en-us/mergedProjects/3D%20Settings/Manage_3D_Settings_%28reference%29.htm'
    $storage='https://learn.microsoft.com/en-us/windows-server/storage/update-firmware'
    $net='https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-netipinterface'
    $tcp='https://learn.microsoft.com/en-us/windows/win32/winsock/socket-options'
    $dma='https://learn.microsoft.com/en-us/windows/security/hardware-security/kernel-dma-protection-for-thunderbolt'
    $intel='https://www.intel.com/content/www/us/en/support/articles/000006636.html'
    @(
        @{Id='WIN-EXPERIMENTAL';Kind='Undefined';Reason='O rotulo nao identifica uma feature/flag publica e sua build.';Steps=@('Anote build e o nome exato da feature pretendida.','Consulte Windows Insider para distinguir recurso opcional de feature flag interna. Sem identificador e documentacao oficial, nao existe receita executavel para este rotulo.');Sources=@($settings);SettingsUri='ms-settings:windowsinsider'},
        @{Id='WIN-HUNG';Kind='Manual';Reason='Procedimento de diagnostico de aplicativo travado, sem converter timeout em velocidade.';Steps=@('Abra o Gerenciador de Tarefas e identifique o aplicativo e o trabalho nao salvo.','Registre horario, versao e evento no Monitor de Confiabilidade; tente fechar pela propria interface antes de encerrar pelo Gerenciador.','Reabra o app e confirme recuperacao dos dados. Nao reduzir HungAppTimeout/WaitToKillAppTimeout para simular desempenho.');Sources=@('https://learn.microsoft.com/en-us/sysinternals/downloads/procdump');Risk='Perda de trabalho ao fechar app';Recovery=@('Use recuperacao do proprio aplicativo; encerrar processo nao tem undo de dados nao salvos.')},
        @{Id='CPU-SMT';Kind='Capability';Capability='SmtFirmwareConfirmed';Reason='SMT/HT e definido pelo firmware e modelo; nao ha toggle Windows universal.';Steps=@('Confira CPU e manual do fabricante da placa/notebook para a opcao SMT/Hyper-Threading.','Somente com opcao confirmada e operador local, registre valor atual e chave de recuperacao antes de uma eventual revisao no firmware.','Nao altere nucleos de inicializacao do msconfig como substituto de SMT. Compare a mesma carga se o OEM permitir uma mudanca.');Sources=@('https://www.intel.com/content/www/us/en/gaming/resources/hyper-threading.html');SettingsUri='ms-settings:about';Maintenance=$true;Restart=$true;Risk='Boot, consumo e throughput';Recovery=@('Volte ao valor exato anotado no firmware pelo procedimento OEM; o app nao restaura firmware.')},
        @{Id='CPU-CSTATES';Kind='Capability';Capability='CpuCstatesFirmwareConfirmed';Reason='Estados de repouso dependem do firmware; suporte nao e inferido do nome da CPU.';Steps=@('Revise primeiro energia/suspensao do Windows e registre consumo/temperatura.','Localize no manual OEM a opcao de C-states e as consequencias para esta plataforma.','Sem documentacao especifica e recuperacao local, encerre a revisao como nao suportada.');Sources=@($power);SettingsUri='ms-settings:powersleep';Maintenance=$true;Restart=$true;Risk='Calor, bateria e boot';Recovery=@('Restauracao externa do valor OEM anotado; nao usar defaults como sinonimo de original.')},
        @{Id='CPU-PBO-OC';Kind='Capability';Capability='CpuTuningConfirmed';Reason='Ryzen Master/XTU exigem modelo e plataforma explicitamente suportados.';Steps=@('Confirme o modelo na lista de suporte Intel XTU ou AMD Ryzen Master, inclusive chipset/OEM.','Na ferramenta oficial, registre os limites e salve o perfil original antes de considerar ajuste manual.','Nao copiar tensao/offset de outra CPU. Qualquer mudanca manual exige avaliacao de temperatura, erros e estabilidade; nenhuma e executada pelo GOAT.');Sources=@($intel,'https://www.amd.com/en/products/software/ryzen-master.html');Maintenance=$true;Restart=$true;Risk='Instabilidade, dano e garantia';Recovery=@('Use o procedimento documentado da ferramenta para retornar ao perfil original; garanta recuperacao OEM se nao iniciar.')},
        @{Id='PWR-MODERN';Kind='Manual';Reason='Diagnosticar o modelo de suspensao, sem prometer conversao S0/S3 por Registry.';Steps=@('Em terminal local, consulte manualmente powercfg /a e anote os estados disponiveis.','Abra Energia e suspensao e registre o sintoma de bateria/retomada.','Consulte OEM se precisar de outro modelo: a existencia de S3 depende da plataforma; nao executar PlatformAoAcOverride como receita universal.');Sources=@($power,'https://learn.microsoft.com/en-us/windows-hardware/design/device-experiences/modern-standby-states');SettingsUri='ms-settings:powersleep';Recovery=@('A consulta nao muda o modelo; retorne os tempos de suspensao aos valores anotados caso o tecnico os ajuste.')},
        @{Id='PWR-SLEEPSTUDY';Kind='Manual';Reason='SleepStudy e diagnostico de Modern Standby, nao um toggle de FPS.';Steps=@('Verifique manualmente powercfg /a; SleepStudy depende do modelo de suspensao suportado.','Em pasta de atendimento autorizada e terminal administrador, execute manualmente powercfg /sleepstudy /output sleepstudy.html.','Abra o HTML local e registre sessoes de consumo/retomada. O comando cria um arquivo e pode conter historico privado: preserve-o localmente.');Sources=@('https://learn.microsoft.com/en-us/windows-hardware/design/device-experiences/modern-standby-sleepstudy',$power);SettingsUri='ms-settings:powersleep';Admin=$true;Recovery=@('Nenhum estado de energia e alterado pelo relatorio; excluir apenas a copia criada pelo atendimento apos guardar as evidencias autorizadas.')},
        @{Id='MEM-COMPRESSION';Kind='Manual';Reason='A revisao usa os cmdlets publicos MMAgent, sem inferir o estado de RAM livre.';Steps=@('Em PowerShell local, consulte Get-MMAgent e registre MemoryCompression, sem alterar outros campos.','Se um teste especifico autorizado exigir alternar, consulte a sintaxe oficial de Enable-MMAgent/Disable-MMAgent -MemoryCompression; confirme privilegio e estado original antes de agir manualmente.','Repita a consulta e meca commit, paginacao e frametime comparavel; nao prometer FPS por desativar compressao.');Sources=@('https://learn.microsoft.com/en-us/powershell/module/mmagent/get-mmagent','https://learn.microsoft.com/en-us/powershell/module/mmagent/enable-mmagent','https://learn.microsoft.com/en-us/powershell/module/mmagent/disable-mmagent');Admin=$true;Recovery=@('Pelo cmdlet oficial correspondente, retorne MemoryCompression ao booleano original anotado; confirme leitura e qualquer reinicio indicado pelo sistema.')},
        @{Id='MEM-STANDBY';Kind='Manual';Reason='Inspecionar cache/pressao em vez de purgar RAM automaticamente.';Steps=@('Registre Available/Committed no Gerenciador de Tarefas durante a mesma carga.','Se necessario, obtenha RAMMap somente da Microsoft e examine Use Counts e arquivos mapeados.','Nao confunda memoria em cache com falta de RAM. Uma purga manual descarta cache e nao pode ser desfeita por snapshot.');Sources=@($ram);StatePath='Memory.UsedPercent';StateSource='Inventory.Memory';Risk='Releituras e stutter ao descartar cache';Recovery=@('Caches descartados precisam ser reconstruidos pela carga; nao existe restauracao exata do cache. Prefira diagnostico sem purga.')},
        @{Id='MEM-RAM-ERROR';Kind='Manual';Reason='Investigar erros mantendo evidencias; nao suprimir diagnostico de hardware.';Steps=@('Registre falha e salve trabalho. Abra Diagnostico de Memoria do Windows pelo menu Iniciar.','Escolha conscientemente quando reiniciar para o teste; em remoto, combine presenca e retorno.','Depois consulte os resultados no Visualizador de Eventos e encaminhe erros ao fabricante.');Sources=@('https://support.microsoft.com/en-us/windows/experience/performance-optimization/how-to-fix-error-0xa-irql-not-less-or-equal');Restart=$true;Maintenance=$true;Recovery=@('O teste nao e rollback de RAM defeituosa; preservar logs e tratar o hardware. Nunca prometer que desativar diagnostico corrige erros.')},
        @{Id='MEM-SVCHOST';Kind='Manual';Reason='Revisao de agrupamento do Service Host por evidencia, sem forcar threshold global.';Steps=@('No Gerenciador de Tarefas, expanda o Service Host e identifique servicos e consumo total.','Confronte a build com a documentacao de service-host grouping; menos processos nao equivale a menos memoria.','Registre servico/processo que apresenta carga e diagnostique-o individualmente; nao aplicar SvcHostSplitThresholdInKB generico.');Sources=@('https://learn.microsoft.com/en-us/windows/application-management/svchost-service-refactoring');Recovery=@('A observacao nao muda agrupamento; qualquer alteracao externa anterior exige restaurar seu snapshot exato, nao um numero sugerido pelo app.')},
        @{Id='STOR-SSD-FIRMWARE';Kind='Capability';Capability='StorageFirmwareConfirmed';Reason='Flash exige modelo, imagem OEM e suporte confirmados; nao existe reversao universal.';Steps=@('Identifique modelo e revisao atual no inventario e no utilitario oficial do fabricante.','Revise release notes, backup de dados, energia estavel e procedimento de recuperacao especifico. A consulta Get-StorageFirmwareInformation somente se aplica a dispositivos/provedores suportados.','A eventual atualizacao e executada manualmente pelo procedimento OEM, fora do app. Nunca escolher imagem so pela marca ou usar arquivo de outro modelo.');Sources=@($storage);Maintenance=$true;Admin=$true;Restart=$true;Risk='Perda de dados ou dispositivo inutilizavel';Recovery=@('Confirme previamente se o OEM admite downgrade/recuperacao; muitos firmwares nao sao reversiveis. Backup de dados nao equivale a rollback de firmware.')},
        @{Id='STOR-NVME-DRIVER';Kind='Manual';Reason='Manutencao assistida do driver instalado, sem ativar caminho oculto de NVMe.';Steps=@('No Gerenciador de Dispositivos, registre controlador, hardware ID, provedor e versao.','Compare com a pagina oficial OEM e notas da versao para a build existente. Garanta backup e driver conhecido localmente.','Somente em janela de manutencao local use Atualizar driver ou Reverter driver quando disponivel na interface. Nao alterar FeatureManagement para forcar driver experimental.');Sources=@('https://learn.microsoft.com/en-us/windows-hardware/drivers/storage/nvme-features-supported-by-stornvme');Maintenance=$true;Admin=$true;Restart=$true;Recovery=@('A opcao Reverter pode nao existir; tenha pacote conhecido, backup e recuperacao de boot. Journal de Registry nao recupera driver/controlador.')},
        @{Id='STOR-IOLATENCY';Kind='Undefined';Reason='IoLatencyCap nao identifica uma API/propriedade publica universal para este dispositivo.';Steps=@('Registre modelo, driver, build e a origem do rotulo.','Use diagnostico de I/O para confirmar sintoma; solicite ao OEM o parametro exato e a documentacao da build. Sem isso, nao ha valor seguro para aplicar.');Sources=@('https://learn.microsoft.com/en-us/windows-hardware/drivers/storage/');Risk='Boot ou I/O instavel'},
        @{Id='GPU-NV-HDCP';Kind='Manual';Vendor='NVIDIA';Reason='A pagina oficial permite verificar capacidade HDCP do monitor selecionado.';Steps=@('Abra Painel NVIDIA > Display > View HDCP Status, se essa secao existir nesta conexao/GPU.','Selecione o monitor certo e registre resultado e alertas de cabo/conexao.','Teste a reproducao do conteudo protegido; o guia verifica compatibilidade, nao oferece remover DRM como otimizacao.');Sources=@('https://www.nvidia.com/content/Control-Panel-Help/vLatest/en-us/mergedProjects/Display/To_verify_if_your_system_is_HDCP-capable.htm');StatePath='GpuCenter.Capabilities.Hdcp';StateSource='Inventory.GpuCenter.Capabilities';Recovery=@('Retorne cabo, porta e modo do monitor aos originais se forem alterados manualmente; o app nao desativa HDCP.')},
        @{Id='GPU-NV-DMA';Kind='Manual';Vendor='NVIDIA';Reason='NVIDIA DMA e um rotulo ambiguo; o procedimento revisa protecao DMA do Windows.';Steps=@('Abra Seguranca do Windows > Seguranca do dispositivo e Informacoes do Sistema para verificar protecao DMA quando reportada.','Registre o estado e a compatibilidade do periferico/driver. Nao traduzir o rotulo NVIDIA em chave privada ou desativacao de IOMMU.');Sources=@($dma);SettingsUri='ms-settings:windowsdefender';StatePath='Security.KernelDmaProtection';StateSource='Inventory.Security';Recovery=@('A consulta nao altera protecao; qualquer manutencao externa segue a recuperacao OEM, mantendo a protecao quando suportada.')},
        @{Id='GPU-NV-THERMAL';Kind='Manual';Vendor='NVIDIA';Reason='Diagnosticar limite termico sem remover protecao do hardware.';Steps=@('Compare sensores disponiveis durante a mesma carga e registre a fonte. Sem sensor, anote indisponivel.','Revise ventilacao, poeira e cooler com o responsavel pelo hardware; interrompa teste em instabilidade.','Nao desativar thermal throttling nem escrever limites privados para mascarar superaquecimento.');Sources=@('https://www.nvidia.com/en-us/geforce/graphics-cards/');Risk='Superaquecimento e dano';Recovery=@('Pare a carga, preserve logs e retorne tuning externo ao perfil conhecido. Reparacao de cooler/hardware exige manutencao apropriada.')},
        @{Id='GPU-NV-PERFLIMIT';Kind='Capability';Vendor='NVIDIA';Capability='NvidiaPowerLimitConfirmed';Reason='PerfCap somente leitura e ajuste de power limit sao procedimentos distintos.';Steps=@('Registre fonte e motivo PerfCap quando a telemetria os fornecer.','Confirme no manual do modelo se existe ajuste suportado; sem controle confirmado, nao existe slider oferecido pelo GOAT.','Com presenca local e perfil original salvo, qualquer ajuste permitido e manual na ferramenta oficial, sem patch de limite ou protecao.');Sources=@($nv);Maintenance=$true;Risk='Potencia, temperatura, garantia e estabilidade';Recovery=@('Reaplique o perfil externo original pela ferramenta que o criou; nao confundir default com o perfil previo.')},
        @{Id='GPU-AMD-POWERGATE';Kind='Capability';Vendor='AMD';Capability='AmdTuningConfirmed';Reason='Adrenalin oferece tuning em modelos selecionados; gating privado nao e controle universal.';Steps=@('Na versao suportada do AMD Software, identifique a GPU e abra Performance Tuning.','Registre o perfil e os campos realmente expostos. Nao criar chaves para force constant voltage ou desligar todos os gates.','Se um ajuste suportado for revisado manualmente, preserve energia/captura e compare estabilidade/temperatura; nao assumir ganho.');Sources=@($amd);Maintenance=$true;Risk='Calor, energia e instabilidade';Recovery=@('Descartar mudancas nao salvas ou importar o perfil original; reset AMD retorna defaults e pode nao reproduzir customizacoes anteriores.')},
        @{Id='GPU-AMD-SPREAD';Kind='Undefined';Vendor='AMD';Reason='Nao foi confirmada opcao publica do Windows/Adrenalin para spread spectrum deste hardware.';Steps=@('Registre GPU/driver e consulte o manual OEM para o significado do rotulo.','Nao escrever firmware ou Registry privado. Se for uma opcao de firmware, encaminhe ao OEM com plano local de recuperacao.');Sources=@($amd);Maintenance=$true;Risk='Clock, interferencia e estabilidade'},
        @{Id='GPU-INTEL-ENERGY';Kind='Undefined';Vendor='Intel';Reason='MC6/energy driver nao identifica um toggle Intel publico generico.';Steps=@('Registre adaptador Intel, versao e personalizacoes OEM.','Revise energia apenas nas opcoes efetivamente expostas pelo aplicativo Intel/OEM. Nao desativar componentes do driver ou criar chave MC6.');Sources=@('https://www.intel.com/content/www/us/en/support/products/80939/graphics.html');SettingsUri='ms-settings:display-advancedgraphics'},
        @{Id='GPU-OC-UV';Kind='Capability';Capability='GpuTuningConfirmed';Reason='Tuning manual depende de modelo, ferramenta oficial e limites confirmados.';Steps=@('Confira suporte do fabricante e identifique a GPU selecionada em sistemas hibridos.','Exporte o perfil original e documente limites/captura/temperaturas antes de qualquer ajuste manual permitido.','Use apenas controles documentados do fabricante; nao copiar offset/tensao universal, fazer flash ou remover protecao termica.');Sources=@($amd,$nv);Maintenance=$true;Risk='Instabilidade, dano e garantia';Recovery=@('Retorne pelo perfil original externo; se houver perda de video, siga o plano local de recuperacao. O app nao prova rollback de tuning.')},
        @{Id='GPU-DMA';Kind='Manual';Reason='Verificar protecao DMA disponivel e compatibilidade dos dispositivos.';Steps=@('Revise Seguranca do dispositivo e o estado Kernel DMA Protection nas Informacoes do Sistema.','Anote fonte e valor, ou desconhecido. Encaminhe incompatibilidade de dispositivo ao fabricante, sem desligar protecao como preset.');Sources=@($dma);SettingsUri='ms-settings:windowsdefender';StatePath='Security.KernelDmaProtection';StateSource='Inventory.Security'},
        @{Id='NET-NAGLE';Kind='Manual';Reason='TCP_NODELAY e comportamento por aplicacao/socket, sem receita universal por interface.';Steps=@('Identifique se a aplicacao usa TCP para o fluxo com problema; UDP nao usa Nagle.','Se houver opcao documentada do proprio jogo/app, anote-a e compare o mesmo cenario.','Encaminhe captura ao fornecedor; nao aplicar TcpAckFrequency/TCPNoDelay a todos os GUIDs de adaptador.');Sources=@($tcp);SettingsUri='ms-settings:network-status';Risk='Conectividade e aumento de pacotes';Recovery=@('Volte a opcao do app ao estado original. Se houve alteracao externa de Registry, use o snapshot exato de cada valor, nao uma receita global.')},
        @{Id='NET-NODELAY';Kind='Manual';Reason='A revisao se limita a opcao TCP_NODELAY que a aplicacao realmente ofereca.';Steps=@('Confirme executavel, versao e protocolo da conexao.','Consulte a documentacao do fornecedor e teste uma opcao de baixa latencia somente se estiver exposta pelo aplicativo.','Nao inventar chave de app ou confundir endpoint de teste com servidor do jogo.');Sources=@($tcp);SettingsUri='ms-settings:network-status';Recovery=@('Restaurar configuracao original do aplicativo e comparar perda/throughput; nenhum reset de rede e executado pelo guia.')},
        @{Id='NET-IPV6';Kind='Manual';Reason='Revisar IPv6 e diagnosticar rotas sem assumir que desativar reduz ping.';Steps=@('Anote adaptador e se o atendimento depende de VPN/IPv6; nunca alterar a interface remota sem presenca local.','Consulte Get-NetIPInterface manualmente e compare conectividade IPv4/IPv6 para o endpoint autorizado.','Use a orientacao Microsoft para um problema especifico; ela recomenda preservar IPv6 e nao desabilitar globalmente como preset.');Sources=@('https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/configure-ipv6-in-windows',$net);SettingsUri='ms-settings:network-status';Maintenance=$true;Risk='Perda de rede/VPN/acesso';Recovery=@('Restaurar bindings, prefix policies e DHCP/DNS exatos anotados; uma queda de rede exige plano de reconexao local.')},
        @{Id='NET-NEIGHBOR';Kind='Manual';Reason='Diagnostico de vizinhos/weak-host em rotas multihomed, sem otimizacao universal.';Steps=@('Mapeie interfaces/VPN e a rota que apresenta falha.','Consulte Get-NetNeighbor e Get-NetIPInterface localmente, sem publicar enderecos do cliente.','So o administrador da rede pode decidir ajuste documentado de WeakHostSend/Receive para esta topologia; nao alterar a interface de suporte por um guia generico.');Sources=@($net,'https://learn.microsoft.com/en-us/powershell/module/nettcpip/get-netneighbor');SettingsUri='ms-settings:network-status';Maintenance=$true;Admin=$true;Recovery=@('Restaurar valores originais da interface e verificar VPN/rotas pelo plano de reconexao.')},
        @{Id='NET-QOS-RESERVED';Kind='Manual';Reason='Revisao de politica QoS; largura reservavel nao cria banda contratada.';Steps=@('Confirme se a maquina e gerenciada e qual politica de QoS esta aplicada.','Com o administrador, revise Policy-based QoS para o aplicativo e o gargalo real de rede.','Nao substituir NonBestEffortLimit por zero como promessa de velocidade; registre throughput e latencia sob carga se forem medidos.');Sources=@('https://learn.microsoft.com/en-us/windows-server/networking/technologies/qos/qos-policy-top');SettingsUri='ms-settings:network-status';Admin=$true;Recovery=@('Qualquer politica manual deve retornar ao estado/documento da organizacao; nao apagar politicas existentes.')},
        @{Id='TIMER-BCDEDIT';Kind='Manual';Reason='Inspecao de flags de depuracao BCD e recuperacao, sem aplicar timer tweak.';Steps=@('Com administrador e chave de recuperacao disponivel, leia manualmente bcdedit /enum {current} e preserve o resultado local.','Compare apenas flags presentes com a documentacao de depuracao. Nao executar /set ou /deletevalue por uma promessa de FPS.','Se houver alteracao externa anterior, use suporte/recovery para restaurar o estado capturado da maquina, nao defaults supostos.');Sources=@($bcd);Admin=$true;Maintenance=$true;Restart=$true;Risk='Boot, BitLocker e acesso';Recovery=@('Restauracao BCD exige plano proprio e estado original. O guia nao reinicia nem modifica o boot.')},
        @{Id='TIMER-HPET';Kind='Manual';Reason='Verificacao de hardware/flags, sem desligar HPET como otimizacao generica.';Steps=@('Registre o sintoma e a configuracao de timers reportada, sem assumir a fonte de clock ativa apenas pelo dispositivo HPET.','Consulte a documentacao BCD e compare frametime com condicoes iguais; nao igualar timer resolution a input lag.','Mudancas de boot/dispositivo requerem engenharia especifica e recuperacao local; nao ha botao de alternancia aqui.');Sources=@($bcd);Maintenance=$true;Restart=$true;Risk='Boot e comportamento de temporizacao'},
        @{Id='INPUT-FIRMWARE';Kind='Capability';Capability='InputFirmwareConfirmed';Reason='Firmware de mouse/teclado exige modelo exato e utilitario OEM.';Steps=@('Identifique modelo/revisao e abra a pagina oficial do fabricante do periferico.','Leia notas, salve perfis e confirme energia/conexao estaveis e procedimento para falha.','Somente o utilitario OEM para o modelo confirmado executa eventual atualizacao manual; nunca um arquivo generico enviado pelo GOAT.');Sources=@('https://learn.microsoft.com/en-us/windows-hardware/drivers/install/updating-device-firmware-using-windows-update');Maintenance=$true;Restart=$true;Risk='Perda de input/dispositivo';Recovery=@('Confirme se o OEM oferece recuperacao/downgrade antes; firmware frequentemente nao tem undo. Garanta teclado/mouse alternativo local.')},
        @{Id='MSI-MODE';Kind='Manual';Reason='MSI e configurado pelo INF/driver do dispositivo; o guia verifica suporte e diagnostico.';Steps=@('No Gerenciador de Dispositivos, registre hardware ID, driver e versao do dispositivo alvo.','Leia a documentacao Microsoft e solicite ao fabricante suporte MSI para este driver. Um exemplo INF nao autoriza editar todos os dispositivos.','Investigue DPC/ISR por ferramenta de diagnostico compativel; mantenha controladores de boot/rede fora de alteracoes genericas.');Sources=@('https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/enabling-message-signaled-interrupts-in-the-registry');Admin=$true;Maintenance=$true;Restart=$true;Risk='BSOD, audio, boot ou rede';Recovery=@('Mudanca externa exige backup exato do dispositivo e recuperacao OEM; o app nao escreve MSISupported/IRQ.')},
        @{Id='SEC-HVCI';Kind='Manual';Reason='Procedimento oficial de integridade de memoria com risco explicito e verificacao apos reinicio.';Steps=@('Abra Seguranca do Windows > Seguranca do dispositivo > Isolamento do nucleo e registre Integridade da memoria.','Confira drivers incompativeis e a documentacao antes de decidir qualquer alteracao manual; desativar reduz protecao do kernel e nao garante FPS.','Se houver mudanca autorizada pela interface, registre-a e verifique o estado depois do reinicio combinado; nunca contornar politica gerenciada.');Sources=@($security);SettingsUri='ms-settings:windowsdefender';StatePath='Security.HvciConfigured';StateSource='Inventory.Security.HvciConfigured (configurado, nao prova estado efetivo)';Admin=$true;Restart=$true;Risk='Reducao de protecao do kernel';Recovery=@('Retorne a selecao original pela mesma interface e confirme estado efetivo/compatibilidade depois do reinicio.')},
        @{Id='SEC-DEFENDER';Kind='Manual';Reason='Revisao na interface oficial de antivirus; exclusao ampla e bypass nao fazem parte do procedimento.';Steps=@('Abra Protecao contra virus e ameacas > Gerenciar configuracoes e registre protecao em tempo real/avisos.','Para carga ou falso positivo, revise historico, agendamento e suporte Microsoft; nao inferir ganho de jogo de uma suspensao de protecao.','Qualquer escolha manual deve ser registrada com plano de reativacao; nao contornar Tamper Protection ou politica da organizacao.');Sources=@('https://support.microsoft.com/en-us/windows/security/windows-security/virus-and-threat-protection-in-the-windows-security-app');SettingsUri='ms-settings:windowsdefender';StatePath='Security.DefenderRealTimeEnabled';StateSource='Inventory.Security';Admin=$true;Risk='Exposicao a malware';Recovery=@('Revisite a mesma pagina, restaure protecoes originais e confirme ausencia de alerta. Exclua somente excecoes de teste criadas e autorizadas, preservando as anteriores.')},
        @{Id='SEC-FIREWALL';Kind='Manual';Reason='Corrigir bloqueio especifico pela interface oficial, mantendo perfis de firewall protegidos.';Steps=@('Abra Firewall e protecao de rede e registre o perfil ativo.','Para um aplicativo bloqueado, prefira Permitir um aplicativo e confirme executavel/publisher/rede necessaria.','Nao desligar todos os perfis ou criar regra ampla para prometer menor ping. Mantenha acesso remoto fora de alteracoes durante suporte.');Sources=@('https://support.microsoft.com/en-us/windows/security/windows-security/firewall-and-network-protection-in-the-windows-security-app');SettingsUri='ms-settings:windowsdefender';StatePath='Security.FirewallEnabled';StateSource='Inventory.Security';Maintenance=$true;Admin=$true;Risk='Exposicao de rede/perda de acesso';Recovery=@('Remova apenas a regra de teste criada e restaure perfil original; preserve politicas gerenciadas e acesso de suporte.')},
        @{Id='SEC-DMA';Kind='Manual';Reason='Estado DMA e suporte do dispositivo, sem desligar protecao.';Steps=@('Confira Kernel DMA Protection em Informacoes do Sistema e Seguranca do dispositivo quando disponivel.','Registre periferico, conexao e a falha de compatibilidade; consulte o OEM para correcao de firmware/driver, sem modificar protecoes por conta do rotulo.');Sources=@($dma);SettingsUri='ms-settings:windowsdefender';StatePath='Security.KernelDmaProtection';StateSource='Inventory.Security'},
        @{Id='SEC-BOOT';Kind='Manual';Reason='Revisao de integridade de boot e recuperacao sem bypass.';Steps=@('Registre Secure Boot/seguranca do dispositivo nas ferramentas Windows e preserve a chave de recuperacao BitLocker de forma privada.','Confira drivers assinados e a documentacao do dispositivo.','Nao usar test-signing, nointegritychecks ou alteracao do hipervisor como otimizacao; resolver incompatibilidade por pacote assinado/OEM.');Sources=@($bcd,$security);SettingsUri='ms-settings:windowsdefender';Maintenance=$true;Admin=$true;Restart=$true;Risk='Boot e perda de protecao';Recovery=@('Use recuperacao oficial do Windows/OEM com identidade e backup corretos; o app nao altera BCD ou Secure Boot.')},
        @{Id='TOOL-ISLC';Kind='Manual';Reason='Fluxo de diagnostico de standby, sem instalacao ou purga automatica.';Steps=@('Registre sintoma de hard faults/commit com a mesma carga antes de atribuir problema a standby.','Use RAMMap da Microsoft para observar a alocacao.','Se uma ferramenta externa for avaliada, confirme origem/licenca e documente efeito; nao criar purga periodica ou timer persistente no atendimento.');Sources=@($ram);StatePath='Memory.UsedPercent';StateSource='Inventory.Memory';Recovery=@('Caches removidos nao podem ser restaurados por journal. Feche ferramenta externa e repita warm-up para comparar corretamente.')},
        @{Id='WIN-POWERTHROTTLE';Kind='Manual';Reason='Revisar modo de energia e processo especifico em vez de desativar gerenciamento global.';Steps=@('Abra Energia e suspensao e registre modo/fonte de energia.','Observe o processo que apresenta queda de resposta e as opcoes realmente expostas pelo Windows para ele.','Compare consumo e carga; nao gravar PowerThrottlingOff global por receita generica.');Sources=@('https://learn.microsoft.com/en-us/windows/win32/api/processthreadsapi/ns-processthreadsapi-process_power_throttling_state');SettingsUri='ms-settings:powersleep';Recovery=@('Restaure modo e preferencia do processo exatamente como anotados; nenhum valor global e escrito pelo app.')},
        @{Id='WIN-MMCSS';Kind='Manual';Reason='Diagnostico de prioridade multimidia com documentacao do MMCSS.';Steps=@('Identifique a tarefa multimidia e os sintomas de audio/renderizacao sob carga.','Leia a documentacao de MMCSS/SystemResponsiveness antes de interpretar qualquer valor existente.','Nao usar SystemResponsiveness=0 como regra universal; alinhe o caso ao fornecedor do aplicativo e mantenha logs.');Sources=@('https://learn.microsoft.com/en-us/windows/win32/procthread/multimedia-class-scheduler-service');Recovery=@('Se um administrador alterar configuracao fora do app, restaurar snapshot com tipo/presenca originais; nao substituir por um suposto default.')},
        @{Id='WIN-DATA-HOSTS';Kind='Manual';Reason='Revisar privacidade e bloqueios de nomes sem substituir hosts por lista opaca.';Steps=@('Abra Privacidade e registre opcoes de diagnostico suportadas pela edicao.','Se ha falha de resolucao, um administrador pode revisar a copia local do hosts e identificar linhas especificas, sem publicar dominios internos.','Qualquer edicao manual exige backup byte a byte e teste de login/Store/Update/jogo; nao importar blocklist indiscriminada.');Sources=@('https://support.microsoft.com/en-us/windows/privacy/diagnostics-feedback-and-privacy-in-windows');SettingsUri='ms-settings:privacy';Admin=$true;Risk='Quebra de login/updates/resolucao';Recovery=@('Restaurar arquivo original completo somente a partir do backup desta maquina; preservar entradas legitimas anteriores.')},
        @{Id='WIN-INVENTORY';Kind='Manual';Reason='Privacidade e coleta de diagnostico pela interface suportada, sem adivinhar collector interno.';Steps=@('Abra Diagnostico e comentarios e registre as opcoes disponiveis para esta edicao/gestao.','Identifique nome real e publisher de qualquer tarefa apontada como problema antes de solicitar manutencao.','Nao desativar um servico por conter Inventory no nome; preservar compatibilidade, atualizacoes e eventos de erro.');Sources=@('https://support.microsoft.com/en-us/windows/privacy/diagnostics-feedback-and-privacy-in-windows');SettingsUri='ms-settings:privacy-feedback';Recovery=@('Restaurar a escolha anterior pela mesma interface; nenhuma tarefa e desativada pelo guia.')},
        @{Id='GPU-VSYNCIDLE';Kind='Undefined';Reason='VSyncIdleTimeout nao possui controle publico universal validado para este driver.';Steps=@('Registre GPU/driver e o problema real de sincronizacao.','Revise V-Sync/cap por jogo no painel oficial ou nas opcoes do jogo; nao substituir um rotulo privado por valor presumido.','Sem documentacao do valor e modelo exatos, registre o item como nao suportado.');Sources=@($nv);SettingsUri='ms-settings:display-advancedgraphics'},
        @{Id='GPU-INTEL-ENERGY-BLOCK';Kind='Undefined';Vendor='Intel';Reason='Nenhuma opcao MC6/energy-driver universal foi confirmada.';Steps=@('Compare driver OEM e Intel para o modelo identificado.','Use apenas as opcoes de energia realmente oferecidas pelo fabricante; a existencia da GPU Intel nao comprova um controle MC6.');Sources=@('https://www.intel.com/content/www/us/en/support/products/80939/graphics.html');SettingsUri='ms-settings:display-advancedgraphics'},
        @{Id='GPU-003';Kind='Capability';Vendor='NVIDIA';Capability='NvidiaPowerLimitConfirmed';Reason='Power limit so pode ser revisado em ferramenta/modelo com controle confirmado.';Steps=@('Identifique GPU e limites expostos pelo fabricante; em notebook valide o OEM primeiro.','Salve o perfil original e confirme energia, temperatura, operador local e recuperacao antes de eventual ajuste manual permitido.','Nenhum limite e aumentado ou desbloqueado automaticamente pelo GOAT.');Sources=@($nv);Maintenance=$true;Risk='Energia, calor e estabilidade';Recovery=@('Restaurar perfil original na mesma ferramenta; um reset para default nao preserva necessariamente customizacoes anteriores.')},
        @{Id='GPU-004';Kind='Capability';Vendor='NVIDIA';Capability='NvidiaClockControlConfirmed';Reason='Clock lock depende de suporte publico do modelo e ferramenta; nao e presumido em GeForce.';Steps=@('Confirme no manual do modelo se ha controle de clock bloqueado suportado e suas restricoes.','Registre frequencias/perfil e objetivo da medicao; sem capacidade confirmada, nao ha acao aplicavel.','Qualquer teste manual ocorre fora do app com presenca local, limites e cancelamento documentados.');Sources=@($nv);Maintenance=$true;Risk='Instabilidade, calor e garantia';Recovery=@('Libere pela mesma ferramenta e recarregue o perfil original; se houver perda de video use o plano local.')},
        @{Id='DISK-004';Kind='Manual';Reason='Revisao de politica de cache e protecao de dados, sem desligar flush universalmente.';Steps=@('No Gerenciador de Dispositivos, abra o disco correto > Propriedades > Politicas, quando a guia existir.','Registre politica atual e confirme a documentacao do dispositivo, protecao contra perda de energia e backup.','Nao selecionar desativacao de flush por uma promessa de FPS; a opcao pode causar perda/corrupcao de dados.');Sources=@('https://learn.microsoft.com/en-us/windows-hardware/drivers/storage/querying-for-the-write-cache-property');Admin=$true;Risk='Perda/corrupcao de dados';Recovery=@('Restaurar escolha original e seguir exigencia de reinicio da interface. Dados perdidos por falha de energia nao sao recuperados por desfazer configuracao.')},
        @{Id='SEC-001';Kind='Manual';Reason='Quatro revisoes oficiais separadas, sem botao para desativar seguranca em lote.';Steps=@('Revise Defender e Integridade da memoria na Seguranca do Windows, registrando estados e politicas.','Para UAC, abra Painel de Controle > Sistema e Seguranca > Alterar configuracoes de Controle de Conta de Usuario e anote o nivel.','Para Update, abra Windows Update e use horario ativo/pausa com prazo se apropriado, preservando atualizacoes de seguranca.','Qualquer decisao manual e individual, auditada e sem promessa de FPS; nao contornar gestao, Tamper Protection ou prompts.');Sources=@($security,'https://support.microsoft.com/en-gb/windows/security/user-account-control-settings','https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-update');SettingsUri='ms-settings:windowsdefender';StatePath='Security';StateSource='Inventory.Security';Admin=$true;Restart=$true;Risk='Exposicao a malware, kernel e updates';Recovery=@('Restaurar cada escolha original separadamente, retomar updates e confirmar avisos de protecao/reinicio. Nao alegar reversao a partir de uma unica chave.')},
        @{Id='SEC-002';Kind='Unsupported';Reason='O GOAT nao oferece bypass de assinatura; o caminho assistido e obter driver compativel assinado.';Steps=@('Registre dispositivo/erro e obtenha pacote assinado para a build pelo fabricante.','Se o pacote nao for compativel, solicite versao suportada ou substitua o dispositivo; nao desligar integridade de codigo para aceitar binario nao confiavel.');Sources=@('https://learn.microsoft.com/en-us/windows-hardware/drivers/install/driver-signing');Risk='Codigo kernel nao confiavel'},
        @{Id='SEC-003';Kind='Unsupported';Reason='Hijack de TrustedInstaller e politica global irrestrita nao sao procedimentos de manutencao do app.';Steps=@('Use o prompt de elevacao normal somente para uma operacao suportada e identificada.','Solicite ao administrador a permissao ou o pacote assinado necessario; nao alterar ImagePath de servico ou executar texto arbitrario para contornar bloqueios.');Sources=@('https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_execution_policies','https://learn.microsoft.com/en-us/windows/security/application-security/application-control/user-account-control/');Risk='Privilegio, persistencia e execucao de codigo'}
    ) | ForEach-Object {[pscustomobject]$_}
}
function Get-GoatAdvancedGuides {
    [CmdletBinding()]
    param([object[]]$Catalog=@(),$Inventory,[switch]$LocalOperatorConfirmed,[switch]$RecoveryPlanConfirmed)
    Set-StrictMode -Off
    if($Catalog.Count -eq 1 -and $Catalog[0].PSObject.Properties['controls']){$Catalog=@($Catalog[0].controls)}
    $definitions=@(Get-GoatAdvancedGuideDefinitions)
    $demo=[bool](Get-GoatAdvancedValue $Inventory 'Demo')
    $isRemote=Get-GoatAdvancedValue $Inventory 'RemoteContext.IsRemote'
    $remoteOrUnknown=($isRemote -ne $false -or @(Get-GoatAdvancedValue $Inventory 'RemoteContext.RemoteProcessNames').Count -gt 0)
    $vendors=@(Get-GoatAdvancedValue $Inventory 'GpuCenter.Devices' | ForEach-Object {$_.Vendor} | Where-Object {$_} | Select-Object -Unique)
    $build=Get-GoatAdvancedValue $Inventory 'OS.Build'
    $buildNumber=0;$windowsSettingsAvailable=([int]::TryParse([string]$build,[ref]$buildNumber) -and $buildNumber -ge 10240)
    foreach($definition in $definitions){
        $record=@($Catalog | Where-Object {$_.id -eq $definition.Id})
        if(-not $record.Count){continue}
        $record=$record[0];$status='MANUAL_GUIDE';$reason=$definition.Reason
        if($definition.Kind -in @('Undefined','Unsupported')){$status='UNSUPPORTED'}
        if($definition.Vendor -and $definition.Vendor -notin $vendors){$status='UNSUPPORTED';$reason+=' Fabricante requerido nao foi confirmado no inventario: '+$definition.Vendor+'.'}
        if($definition.Capability){
            $gpuCapability=Get-GoatAdvancedValue $Inventory ('GpuCenter.Capabilities.'+$definition.Capability)
            $systemCapability=Get-GoatAdvancedValue $Inventory ('Capabilities.'+$definition.Capability)
            $confirmed=(($gpuCapability -is [bool] -and $gpuCapability) -or ($systemCapability -is [bool] -and $systemCapability))
            if(-not $confirmed){$status='UNSUPPORTED';$reason+=' Capacidade especifica nao confirmada: '+$definition.Capability+'.'}
        }
        $maintenanceReady=(-not $definition.Maintenance -or -not $remoteOrUnknown -or ($LocalOperatorConfirmed -and $RecoveryPlanConfirmed))
        if($definition.Maintenance -and -not $maintenanceReady){$reason+=' Em remoto/incerto, somente revisao documental: exigir pessoa local e plano de recuperacao antes da manutencao.'}
        $value=if($definition.StatePath -and -not $demo){Get-GoatAdvancedValue $Inventory $definition.StatePath}else{$null}
        $state=[pscustomobject]@{Known=($null -ne $value);Value=$value;Source=$definition.StateSource;Status=$(if($demo){'DEMO_NOT_QUERIED'}elseif($null -eq $value){'UNKNOWN'}else{'INVENTORY_SNAPSHOT'});Note='Estado anterior exige confirmacao manual atual; ausencia nao significa desativado.'}
        $uri=[string]$definition.SettingsUri
        $settingsAllowed=($status -eq 'MANUAL_GUIDE' -and $windowsSettingsAvailable -and (Test-GoatAdvancedSettingsUri $uri))
        $steps=@('Antes: identifique sintoma, objetivo, build/dispositivo e registre a configuracao atual com consentimento.')+@($definition.Steps)+@('Depois: registre escolha real, verificacao, efeitos colaterais e pendencias no atendimento. Abrir guia/configuracao nao declara alteracao aplicada ou ganho medido.')
        $recovery=if($definition.Recovery){@($definition.Recovery)}else{@('A revisao nao modifica o sistema. Se houver mudanca manual externa, sua recuperacao exige estado original e procedimento especifico; o journal do GOAT nao prova reversao dela.')}
        [pscustomobject]@{
            Id=$definition.Id;Title=$record.title;Status=$status;Risk=$(if($definition.Risk){$definition.Risk}else{$record.risk});Mode='C_MANUAL';Reason=$reason
            Steps=$steps;Recovery=$recovery;Sources=@($definition.Sources);SettingsUri=$uri;CanOpenSettings=[bool]$settingsAllowed;SettingsAvailability='Pagina solicitavel; o Windows pode ocultar opcoes por build, hardware ou politica. Abrir nao comprova aplicacao.'
            AvailableManual=($status -eq 'MANUAL_GUIDE');CanAutomate=$false;CanApply=$false;CanMutate=$false
            State=$state;Before='Registrar estado real na interface/ferramenta indicada; valores ausentes permanecem desconhecidos.';ExpectedEffect='Revisao/diagnostico ou manutencao manual especifica. FPS e input lag nao medidos.'
            Prerequisites=[pscustomobject]@{AdminRequired=[bool]$definition.Admin;StablePowerRequired=[bool]$definition.Maintenance;BackupRequired=[bool]$definition.Maintenance;RestartMayBeRequired=[bool]$definition.Restart;RemoteOrUnknown=$remoteOrUnknown;LocalOperatorConfirmed=[bool]$LocalOperatorConfirmed;RecoveryPlanConfirmed=[bool]$RecoveryPlanConfirmed;MaintenanceReady=[bool]$maintenanceReady;Note='Nao elevar, reiniciar ou iniciar utilitario automaticamente.'}
            OriginalExecutionClass=$record.execution_class;SourceExecutionClass=$record.source_execution_class;SourcePath=$record.source_path;SourceRecordPreserved=($null -ne $record.source_record);ImplementationStatus=$status;Demo=$demo;SourcesChecked='2026-10-28'
        }
    }
}
